//! Compressed copies of the resources the library embeds at build time.
//!
//! The raw templates and tables total about 4 MB; storing them zlib-compressed
//! (generated by `tools/compress-resources.py`) and inflating once on first
//! use keeps a release binary roughly 2.6 MB smaller without changing any
//! behaviour.

use std::sync::LazyLock;

macro_rules! bytes_resource {
    ($name:ident, $file:literal) => {
        pub fn $name() -> &'static [u8] {
            static DATA: LazyLock<Vec<u8>> = LazyLock::new(|| {
                crate::deflate::zlib_decompress(include_bytes!($file))
                    .expect("corrupt embedded resource")
            });
            DATA.as_slice()
        }
    };
}

macro_rules! text_resource {
    ($name:ident, $file:literal) => {
        pub fn $name() -> &'static str {
            static DATA: LazyLock<String> = LazyLock::new(|| {
                let bytes = crate::deflate::zlib_decompress(include_bytes!($file))
                    .expect("corrupt embedded resource");
                String::from_utf8(bytes).expect("embedded resource is not UTF-8")
            });
            DATA.as_str()
        }
    };
}

